for state,items in P0_NORTH_WEST.items():P[state].extend(items)
ROLE_DEFAULTS={
"airport":"baggage handler|traveller|security officer","carnival_workshop":"costume maker|dancer|drummer","cattle_market":"cattle trader|herder|loader","church":"usher|choir member|elder","community_hall":"community leader|elder|youth organiser","conservation_office":"park ranger|wildlife officer|researcher","craft_market":"weaver|carver|artisan","emir_palace":"palace guard|court historian|horse groom","factory_gate":"factory worker|security man|artisan","farm":"farmer|produce buyer|extension worker","festival_ground":"festival organiser|drummer|food vendor","fishing_jetty":"fisherman|boat operator|fish seller","hotel":"receptionist|tour guide|security guard","jetty":"boat operator|ticket seller|passenger","library":"librarian|archivist|researcher","market":"market woman|trader|loader","mining_site":"miner|quarry worker|mineral trader","monument":"heritage guide|caretaker|photographer","mosque":"imam|mallam|attendant","motor_park":"agbero|driver|conductor","museum":"museum guide|historian|archaeologist","nightclub":"bouncer|bartender|DJ","palace":"palace guard|court historian|chief","radio_station":"presenter|producer|musician","railway_station":"railway worker|ticket seller|passenger","refinery":"engineer|security man|tanker driver","restaurant":"cook|server|food vendor","sacred_grove":"custodian|priestess|guide","seaport":"dockworker|clearing agent|customs officer","traditional_council":"chief|elder|court secretary","university":"lecturer|student|researcher","waterfront":"boatman|fish seller|dockworker"}
for state,seeds in SEEDS.items():
 peers=[x for x in CLUSTERS[next(k for k,v in CLUSTERS.items() if state in v)] if x!=state]
 for i,(dimension,venue,dialogue) in enumerate(seeds):
  candidates="|".join(dict.fromkeys((state,peers[i%len(peers)],peers[(i*2+1)%len(peers)])))
  P[state].append((dimension,candidates,venue,ROLE_DEFAULTS[venue],dialogue,"P0 semantic editorial research; specific source verification required"))
for state,seeds in FINAL_SEEDS.items():
 peers=[x for x in CLUSTERS[next(k for k,v in CLUSTERS.items() if state in v)] if x!=state]
 for i,(dimension,venue,dialogue) in enumerate(seeds):
  candidates="|".join(dict.fromkeys((state,peers[(i+2)%len(peers)],peers[(i*3+4)%len(peers)])))
