VENUE_NAMES={"emir_palace":"Emir's palace","factory_gate":"Factory gate","waterfront":"Waterfront","jetty":"Jetty","community_hall":"Community hall","conservation_office":"Conservation office","carnival_workshop":"Carnival workshop","festival_ground":"Festival ground","farm":"Farm","seaport":"Seaport","refinery":"Refinery"}
def pidgin_variant(text):
 replacements=[("He kept asking ","That person dey ask "),("He was looking for ","That person dey find "),("He was travelling ","That person dey travel "),("He was reading ","That person dey read "),("He was tracing ","That person dey trace "),("He was asking ","That person dey ask "),("He wanted ","The person say e dey find "),("He asked ","The person ask "),("He enquired ","The person ask "),("He requested ","The person ask for "),("He bought ","The person buy "),("He mentioned ","The person talk about "),("He priced ","The person price "),("He examined ","The person check "),("He discussed ","The person talk about "),("He rejected ","The person no gree for "),("He stared ","The person look "),("His papers mentioned ","The paper wey e carry mention ")]
 for old,new in replacements:
  if text.startswith(old):return new+text[len(old):]
 return text.replace("The traveller ","That person ",1)
def main():
 out=[];base_n=1
 for state,items in P.items():
  for item_number,item in enumerate(items):
   dimension,candidates,venue,roles,dialogue=item[:5];source=item[5] if len(item)>5 else "Curated from the source-linked knowledge database; editorial review required"
   if venue=="motor_park" and "agbero" not in roles.split("|"):roles="agbero|"+roles
   if item_number<4:atom_id=f"SCA-{base_n:04d}";base_n+=1
   else:
    region=next(k for k,v in CLUSTERS.items() if state in v).upper().replace('_','-')
    atom_id=f"SCA-P0-{region}-{state.upper().replace(' ','-')}-{item_number-3:02d}"
   out.append({"atom_id":atom_id,"state":state,"cluster":next(k for k,v in CLUSTERS.items() if state in v),"dimension":dimension,"candidate_states":candidates,"venue_id":venue,"venue_name":VENUE_NAMES.get(venue,venue.replace('_',' ').title()),"witness_roles":roles,"dialogue":dialogue,"difficulty":"2","source":source})
 OUT.parent.mkdir(parents=True,exist_ok=True)
 with OUT.open("w",encoding="utf-8",newline="") as f:
  w=csv.DictWriter(f,fieldnames=list(out[0]),lineterminator="\n");w.writeheader();w.writerows(out)
 variants=[]
 for atom in out:
  text=atom["dialogue"];lower=text[0].lower()+text[1:]
  standard={
   "easy":[text,f"The traveller was quite specific: {lower}",f"I can tell you exactly what I heard: {lower}"],
   "medium":[text.replace("He ","The traveller ",1),f"What stayed with me was this: {lower}",f"The detail I wrote down was that {lower}"],
   "hard":[f"The person never named the place, but {lower}",f"The only useful detail I caught was this: {lower}",f"Put this in your notebook: {lower}"],
  }
  pidgin_base=pidgin_variant(text);pidgin_lower=pidgin_base[0].lower()+pidgin_base[1:]
  pidgin={
   "easy":[pidgin_base,f"Na wetin I hear be this: {pidgin_lower}",f"I remember am well: {pidgin_lower}"],
   "medium":[pidgin_base,f"Na this one remain for my mind: {pidgin_lower}",f"The main thing wey I notice be say {pidgin_lower}"],
   "hard":[f"The person no call the place name, but {pidgin_lower}",f"Na only this small detail I fit give you: {pidgin_lower}",f"Make you write this one down: {pidgin_lower}"],
  }
  for register,sets in (("English",standard),("Nigerian Pidgin",pidgin)):
   for difficulty,texts in sets.items():
    for number,dialogue in enumerate(texts,1):variants.append({"variant_id":f"{atom['atom_id']}-{difficulty[0].upper()}-{register[0]}-{number}","atom_id":atom["atom_id"],"difficulty":difficulty,"speech_register":register,"variant_number":number,"dialogue":dialogue})
 with VARIANTS.open("w",encoding="utf-8",newline="") as f:
  w=csv.DictWriter(f,fieldnames=list(variants[0]),lineterminator="\n");w.writeheader();w.writerows(variants)
 print(f"Created {len(out)} clue atoms for {len(P)} states and {len(variants)} dialogue variants")
if __name__=="__main__":main()
